 <div className="reminders-list-tools"><span>{tab==='completed'?`${done.length} completed`:`${groups.reduce((sum,[,items])=>sum+items.length,0)} reminders`}</span><label><Search size={15}/><input aria-label="Search reminders" placeholder="Find a reminder" value={query} onChange={e=>setQuery(e.target.value)}/></label></div>
