function Account({ws,notify,retainPreferences,restoreGuestAppearance}){const [selection,setSelection]=useState({pinned:false,notes:false,reminders:false,wallpaper:false,shortcuts:false}),[importBusy,setImportBusy]=useState(false);const [tab,setTab]=useState('signin'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState('');async function submit(e){e.preventDefault();setBusy(true);setMessage('');try{if(tab==='signup'){const {data,error}=await cloud.auth.signUp({email,password,options:{emailRedirectTo:'https://i-am-dev-god.github.io/OS-GOD/'}});if(error)throw error;setMessage(data.session?'Account created.':'Check your email to confirm your account, then sign in.')}else{const {error}=await cloud.auth.signInWithPassword({email,password});if(error)throw error;notify('Welcome back')}}catch(e){setMessage(e.message||'Could not connect. Please try again.')}finally{setBusy(false)}}return <div className="utility-content account-content"><div className="account-hero"><span className="account-hero-icon"><Cloud size={25}/></span><span className="eyebrow">YOUR SPACE, EVERYWHERE</span><h2>{ws.session?'Your account':'Your thoughts,\nwherever you go.'}</h2><p>{ws.session?'Your notes can sync across devices when you’re online.':'Sign in to sync your notes across devices. Or stay in guest mode — your notes will be saved on this device.'}</p></div>{ws.session?<><div className="signed-in"><span className="user-avatar">{ws.session.user.email?.[0]?.toUpperCase()}</span><span><b>{ws.session.user.email}</b><small>{ws.status}</small></span><Check size={18}/></div><div className="import-box retain-box"><b>Bring your guest workspace</b><p>Choose what to copy to this account. Guest originals stay on this device. Notes are copied, not linked; repeating the import creates duplicates.</p>{[['pinned','Pinned / favorite notes'],['notes','Other notes'],['reminders','Standalone reminders'],['wallpaper','Wallpaper'],['shortcuts','Desktop shortcut visibility']].map(([key,label])=><label key={key}><input type="checkbox" checked={selection[key]} onChange={e=>setSelection(v=>({...v,[key]:e.target.checked}))}/>{label}</label>)}<button disabled={importBusy||!Object.values(selection).some(Boolean)} onClick={async()=>{setImportBusy(true);try{if((selection.wallpaper||selection.shortcuts)&&!await retainPreferences(selection))return;const n=ws.importGuest(selection);notify(`Copied ${n} guest items${selection.wallpaper||selection.shortcuts?' and saved appearance':''}`);setSelection({pinned:false,notes:false,reminders:false,wallpaper:false,shortcuts:false})}finally{setImportBusy(false)}}}>Copy selected items <ArrowRight size={14}/></button><small>Wallpaper and shortcut visibility sync after you choose them. Note history stays on this device.</small></div><div className="account-buttons"><button onClick={()=>{ws.sync();notify('Checking for changes')}}><RefreshCw size={15}/> Sync now</button><button onClick={async()=>{restoreGuestAppearance();await cloud.auth.signOut();notify('Signed out')}}><LogOut size={15}/> Sign out</button></div><AccountDeletion ws={ws} notify={notify} restoreGuestAppearance={restoreGuestAppearance}/><p className="account-foot">Signing out doesn’t erase this account’s cached notes from this browser. Cloud notes are not end-to-end encrypted.</p></>:<><div className="auth-tabs"><button className={tab==='signin'?'active':''} onClick={()=>{setTab('signin');setMessage('')}}>Sign in</button><button className={tab==='signup'?'active':''} onClick={()=>{setTab('signup');setMessage('')}}>Create account</button></div><form key={tab} className="auth-form" onSubmit={submit}><label>Email address<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required autoComplete="email"/></label><label>Password<input type="password" minLength={6} value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 6 characters" required autoComplete={tab==='signup'?'new-password':'current-password'}/></label>{message&&<div className="auth-message" role="status">{message}</div>}<button className="auth-submit" type="submit" disabled={busy}>{busy?'One moment…':tab==='signin'?'Sign in to your space':'Create your account'} <ArrowRight size={16}/></button></form><div className="privacy-note"><LockKeyhole size={14}/> Account notes are private to your account, but not end-to-end encrypted.</div></>}</div>}

function AccountDeletion({ws,notify,restoreGuestAppearance}){
 const [expanded,setExpanded]=useState(false),[password,setPassword]=useState(''),[confirmation,setConfirmation]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const remove=async e=>{e.preventDefault();if(confirmation!=='DELETE'||!password||busy)return;setBusy(true);setError('');const id=ws.session.user.id,email=ws.session.user.email;
 try{const {error:authError}=await cloud.auth.signInWithPassword({email,password});if(authError)throw authError;setPassword('');const {error:deleteError}=await cloud.rpc('stillspace_delete_my_account');if(deleteError)throw deleteError;
 // The remote account is already gone; clearing local auth must not change the deletion result.
 try{await cloud.auth.signOut({scope:'local'})}catch{}restoreGuestAppearance();
 try{for(const key of ['stillspace:notes:','stillspace:history:','stillspace:reminder-notifications:'])localStorage.removeItem(key+id)}catch{}
 notify('Account deleted');setExpanded(false);
 }catch(err){setError(err.message||'Could not delete account. Please try again.')}finally{setBusy(false)}};
 return <details className="account-danger" open={expanded} onToggle={e=>{setExpanded(e.currentTarget.open);if(!e.currentTarget.open){setPassword('');setConfirmation('');setError('')}}}><summary>Delete account</summary><p>Permanently delete your account, cloud notes, reminders, saved appearance and workspace links. This cannot be undone. Guest data stays on this device. Copies on other devices and backups may remain.</p><form onSubmit={remove}><label>Confirm your password<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></label><label>Type DELETE to confirm<input value={confirmation} onChange={e=>setConfirmation(e.target.value)} autoComplete="off" required/></label>{error&&<p role="alert">{error}</p>}<button disabled={busy||confirmation!=='DELETE'||!password}>{busy?'Deleting…':'Permanently delete account'}</button></form></details>
}

export const root=createRoot(document.getElementById('root'));
root.render(<App/>);
if('serviceWorker' in navigator&&import.meta.env.PROD)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.warn));
